#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

_seed_from_k8s_secret() {
  local key="$1" secret_file="$2"
  if [[ -f "$secret_file" && -z "$(_existing "$key" || true)" ]]; then
    local val
    val=$(grep -E "^[[:space:]]+${key}:" "$secret_file" | head -n1 | sed -E 's/^[[:space:]]+[A-Z_]+:[[:space:]]*"?([^"]*)"?/\1/' || true)
    if [[ -n "$val" && "$val" != *"your_"*"_here"* ]]; then
      write_env "$key" "$val" >/dev/null 2>&1 || true
    fi
  fi
}

run_wizard() {

TOTAL_STAGES=8
ENV_FILE="${ENV_FILE:-curator/.env}"
K8S_SECRET_FILE="${K8S_SECRET_FILE:-deploy/curator/secret.yaml}"

# Pre-seed any credentials that already exist in deploy/curator/secret.yaml
_seed_from_k8s_secret "OPENROUTER_API_KEY" "$K8S_SECRET_FILE"
_seed_from_k8s_secret "REDDIT_CLIENT_ID" "$K8S_SECRET_FILE"
_seed_from_k8s_secret "REDDIT_CLIENT_SECRET" "$K8S_SECRET_FILE"
_seed_from_k8s_secret "REDDIT_REFRESH_TOKEN" "$K8S_SECRET_FILE"
_seed_from_k8s_secret "REDDIT_USER_AGENT" "$K8S_SECRET_FILE"
_seed_from_k8s_secret "DATABASE_URL" "$K8S_SECRET_FILE"

banner "Curator LoRA Training & Inference Credentials Setup"

# ── Stage 1: OpenRouter API Key ───────────────────────────────────────────
stage "OpenRouter: Benchmark & Vision Model API Key"
say "OpenRouter powers Curator map evaluations, vision theme suggestions, and physical descriptions."
open_url "https://openrouter.ai/settings/keys"
step "On the OpenRouter API Keys page, create a new key or copy an existing key."
step "Ensure your OpenRouter account has positive credit balance."
ask_secret OPENROUTER_API_KEY "Paste your OpenRouter API key (sk-or-v1-...):"
write_env OPENROUTER_API_KEY "$OPENROUTER_API_KEY"

# ── Stage 2: Hugging Face Token & Model License ───────────────────────────
stage "Hugging Face: FLUX.3 Klein Base License & Access Token"
say "LoRA fine-tuning targets black-forest-labs/flux-3-image-klein-base (ADR-0008)."
say "This repository is gated under the FLUX Kommunity License. You must accept terms first."
open_url "https://huggingface.co/black-forest-labs/flux-3-image-klein-base"
step "Review and accept the FLUX Kommunity License agreement on Hugging Face."
pause "Once accepted on the model card page, press Enter to generate your token..."
open_url "https://huggingface.co/settings/tokens"
step "Click 'Create new token' (Token type: Read)."
step "Name the token (e.g. 'dungeonforge-flux3-runner') and click 'Create token'."
ask_secret HF_TOKEN "Paste your Hugging Face User Access Token (starts with hf_):"
write_env HF_TOKEN "$HF_TOKEN"

# ── Stage 3: Cloudflare R2 Artifact Storage ──────────────────────────────
stage "Cloudflare R2: Dataset Snapshots & LoRA Artifacts"
say "Cloudflare R2 provides S3-compatible storage for Dataset Snapshots and LoRA adapters."
say "Modal and WaveSpeed fetch artifacts directly by public HTTPS URL (ADR-0008, ADR-0009)."
open_url "https://dash.cloudflare.com/"
step "Navigate to 'R2 Object Storage' in the left-hand navigation menu."
step "Locate your 'Account ID' on the right sidebar of the R2 overview page and copy it."
ask R2_ACCOUNT_ID "Paste your Cloudflare Account ID:"
write_env R2_ACCOUNT_ID "$R2_ACCOUNT_ID"

R2_ENDPOINT="https://${R2_ACCOUNT_ID}.r2.cloudflarestorage.com"
write_env R2_ENDPOINT "$R2_ENDPOINT"

step "Under R2, create or choose your artifacts bucket."
ask R2_BUCKET_NAME "Enter your R2 bucket name [dungeonforge-artifacts]:"
R2_BUCKET_NAME="${R2_BUCKET_NAME:-dungeonforge-artifacts}"
write_env R2_BUCKET_NAME "$R2_BUCKET_NAME"

open_url "https://dash.cloudflare.com/?to=/:account/r2/api-tokens"
step "Click 'Manage R2 API Tokens' -> 'Create API Token'."
step "Set Permissions: 'Object Read & Write' (scoped to your bucket or all buckets)."
step "Click 'Create API Token' and copy the Access Key ID and Secret Access Key."
ask R2_ACCESS_KEY_ID "Paste your R2 Access Key ID:"
ask_secret R2_SECRET_ACCESS_KEY "Paste your R2 Secret Access Key:"
write_env R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
write_env R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"

step "Enable public HTTP read access for artifacts (needed by Modal & WaveSpeed):"
step "Go to your bucket -> 'Settings' tab -> scroll to 'Public Access'."
step "Enable 'R2.dev subdomain' (or configure a custom domain like https://artifacts.yourdomain.com)."
ask R2_PUBLIC_URL "Paste the public URL prefix (e.g. https://pub-xxxxxx.r2.dev):"
write_env R2_PUBLIC_URL "$R2_PUBLIC_URL"

# ── Stage 4: Modal Cloud GPU Training Runner ─────────────────────────────
stage "Modal: GPU Training Runner Credentials"
say "Modal executes ai-toolkit fine-tuning on L40S 48GB GPU instances (ADR-0008, ADR-0009)."
open_url "https://modal.com/settings/tokens"
step "Click 'New Token' to create credentials for the Modal CLI and SDK."
note "Alternatively, if modal CLI is installed locally, you can run 'modal token new'."
ask MODAL_TOKEN_ID "Paste your Modal Token ID (starts with ak-):"
ask_secret MODAL_TOKEN_SECRET "Paste your Modal Token Secret (starts with as-):"
write_env MODAL_TOKEN_ID "$MODAL_TOKEN_ID"
write_env MODAL_TOKEN_SECRET "$MODAL_TOKEN_SECRET"

say "Next, configure the Curator Modal Runner FastAPI bridge endpoint (ADR-0009)."
note "If your training runner FastAPI app is not yet deployed, press Enter to keep empty."
ask CURATOR_MODAL_ENDPOINT "Modal runner endpoint URL [or Enter to skip]:"
if [[ -n "$CURATOR_MODAL_ENDPOINT" ]]; then
  write_env CURATOR_MODAL_ENDPOINT "$CURATOR_MODAL_ENDPOINT"
fi
ask_secret CURATOR_MODAL_TOKEN "Modal runner bearer auth token [or Enter to skip]:"
if [[ -n "$CURATOR_MODAL_TOKEN" ]]; then
  write_env CURATOR_MODAL_TOKEN "$CURATOR_MODAL_TOKEN"
fi

# ── Stage 5: WaveSpeedAI Serverless LoRA Inference ────────────────────────
stage "WaveSpeedAI: Serverless LoRA Inference"
say "WaveSpeedAI serves the trained FLUX 3 Klein adapter (ADR-0008, ADR-0010, Issue #208)."
say "Provides text-to-image ($0.015/map) and edit ($0.021/map) endpoints with custom LoRAs."
open_url "https://wavespeed.ai/"
step "Log in to WaveSpeedAI and navigate to API Keys in the dashboard/console."
step "Create or copy an API Key."
ask_secret WAVESPEED_API_KEY "Paste your WaveSpeed API key:"
write_env WAVESPEED_API_KEY "$WAVESPEED_API_KEY"

# ── Stage 6: PostgreSQL Catalog Database Connection ──────────────────────
stage "PostgreSQL: Catalog Database Connection"
say "ADR-0011 moves Curator domain metadata (candidates, curated maps, rejections,"
say "datasets, training runs and adapters) from the on-disk catalog into PostgreSQL."
note "Set DATABASE_URL to the in-cluster DSN to use PostgreSQL, e.g.:"
note "  postgres://curator:<password>@shared-postgres-rw.database.svc.cluster.local:5432/curator"
note "Leave empty to keep the filesystem catalog fallback."
ask_secret DATABASE_URL "Paste the curator PostgreSQL DSN — Enter keeps the filesystem catalog fallback (empty DSN):" || true
if [[ -n "${DATABASE_URL:-}" ]]; then
  write_env DATABASE_URL "$DATABASE_URL"
fi

# ── Stage 7: Authenticated API Connectivity Verification ─────────────────
stage "Verification: Authenticated API Connectivity"
say "Testing authenticated API reachability across configured providers..."

# 1. OpenRouter
say "Checking OpenRouter API..."
if curl -s -f -o /dev/null -H "Authorization: Bearer $OPENROUTER_API_KEY" https://openrouter.ai/api/v1/auth/key 2>/dev/null; then
  printf '  %s✓ OpenRouter: Authenticated successfully%s\n' "$GREEN" "$RESET"
else
  warn "OpenRouter: Authentication failed or endpoint unreachable"
fi

# 2. Hugging Face
say "Checking Hugging Face API..."
hf_user=$(curl -s -f -H "Authorization: Bearer $HF_TOKEN" https://huggingface.co/api/whoami-v2 2>/dev/null | grep -o '"name":"[^"]*"' | head -n1 | cut -d'"' -f4 || true)
if [[ -n "$hf_user" ]]; then
  printf '  %s✓ Hugging Face: Authenticated as @%s%s\n' "$GREEN" "$hf_user" "$RESET"
else
  warn "Hugging Face: Token validation failed or network unreachable"
fi

# 3. Cloudflare R2 Public URL
say "Checking Cloudflare R2 Public URL..."
if [[ -n "$R2_PUBLIC_URL" ]]; then
  r2_code=$(curl -s -o /dev/null -w "%{http_code}" "$R2_PUBLIC_URL" 2>/dev/null || echo "000")
  if [[ "$r2_code" =~ ^(200|403|404)$ ]]; then
    printf '  %s✓ Cloudflare R2 Public URL reachable (HTTP %s)%s\n' "$GREEN" "$r2_code" "$RESET"
  else
    warn "Cloudflare R2 Public URL returned HTTP $r2_code"
  fi
fi

# 4. WaveSpeed API
say "Checking WaveSpeed API..."
if [[ -n "$WAVESPEED_API_KEY" ]]; then
  ws_code=$(curl -s -o /dev/null -w "%{http_code}" -H "Authorization: Bearer $WAVESPEED_API_KEY" https://api.wavespeed.ai/v1/models 2>/dev/null || echo "000")
  if [[ "$ws_code" =~ ^(200|404)$ ]]; then
    printf '  %s✓ WaveSpeed API reachable (HTTP %s)%s\n' "$GREEN" "$ws_code" "$RESET"
  else
    warn "WaveSpeed: Received HTTP $ws_code (check your key at https://wavespeed.ai)"
  fi
fi

pause "Review verification checks above. Press Enter to proceed to Kubernetes secret sync."

# ── Stage 8: Kubernetes Cluster Secret Sync ──────────────────────────────
stage "Kubernetes: Cluster Secret Sync"
say "Generating updated Kubernetes Secret manifest: $K8S_SECRET_FILE"

# Preserve existing Reddit credentials if present
REDDIT_CLIENT_ID=$(_existing REDDIT_CLIENT_ID || true)
REDDIT_CLIENT_SECRET=$(_existing REDDIT_CLIENT_SECRET || true)
REDDIT_REFRESH_TOKEN=$(_existing REDDIT_REFRESH_TOKEN || true)
REDDIT_USER_AGENT=$(_existing REDDIT_USER_AGENT || true)
DATABASE_URL=$(_existing DATABASE_URL || true)

mkdir -p "$(dirname "$K8S_SECRET_FILE")"
cat <<EOF > "$K8S_SECRET_FILE"
apiVersion: v1
kind: Secret
metadata:
  name: curator-secrets
  namespace: curator
  labels:
    app: curator
    app.kubernetes.io/name: curator
type: Opaque
stringData:
  OPENROUTER_API_KEY: "${OPENROUTER_API_KEY:-}"
  HF_TOKEN: "${HF_TOKEN:-}"
  MODAL_TOKEN_ID: "${MODAL_TOKEN_ID:-}"
  MODAL_TOKEN_SECRET: "${MODAL_TOKEN_SECRET:-}"
  CURATOR_MODAL_ENDPOINT: "${CURATOR_MODAL_ENDPOINT:-}"
  CURATOR_MODAL_TOKEN: "${CURATOR_MODAL_TOKEN:-}"
  R2_ACCOUNT_ID: "${R2_ACCOUNT_ID:-}"
  R2_ACCESS_KEY_ID: "${R2_ACCESS_KEY_ID:-}"
  R2_SECRET_ACCESS_KEY: "${R2_SECRET_ACCESS_KEY:-}"
  R2_BUCKET_NAME: "${R2_BUCKET_NAME:-dungeonforge-artifacts}"
  R2_ENDPOINT: "${R2_ENDPOINT:-}"
  R2_PUBLIC_URL: "${R2_PUBLIC_URL:-}"
  WAVESPEED_API_KEY: "${WAVESPEED_API_KEY:-}"
  REDDIT_CLIENT_ID: "${REDDIT_CLIENT_ID:-}"
  REDDIT_CLIENT_SECRET: "${REDDIT_CLIENT_SECRET:-}"
  REDDIT_REFRESH_TOKEN: "${REDDIT_REFRESH_TOKEN:-}"
  REDDIT_USER_AGENT: "${REDDIT_USER_AGENT:-DungeonForge-Curator/1.0}"
  DATABASE_URL: "${DATABASE_URL:-}"
EOF
chmod 600 "$K8S_SECRET_FILE"
printf '  %s✓ Generated secret manifest:%s %s (mode 0600)\n' "$GREEN" "$RESET" "$K8S_SECRET_FILE"

if command -v kubectl >/dev/null 2>&1 && kubectl get namespace curator >/dev/null 2>&1; then
  say "Kubernetes connection active (namespace 'curator' found)."
  if confirm "Apply curator-secrets to your Kubernetes cluster now?"; then
    kubectl apply -f "$K8S_SECRET_FILE"
    printf '  %s✓ Successfully applied secret to Kubernetes cluster%s\n' "$GREEN" "$RESET"
    kubectl get secret curator-secrets -n curator
    if confirm "Restart Curator pod to mount updated secrets (kubectl rollout restart)?"; then
      kubectl rollout restart deployment/curator -n curator
      kubectl rollout status deployment/curator -n curator --timeout=90s || true
    fi
  else
    note "Skipped kubectl apply. You can apply it later with:"
    note "  kubectl apply -f $K8S_SECRET_FILE"
  fi
else
  warn "kubectl not connected or namespace 'curator' not found."
  note "Apply the secret manually when connected to your cluster:"
  note "  kubectl apply -f $K8S_SECRET_FILE"
fi

finish
}

run_wizard "$@"; exit
